CREATE TABLE ezurlalias_ml (parent INTEGER DEFAULT 0 NOT NULL, text_md5 VARCHAR(32) DEFAULT '' NOT NULL, "action" CLOB NOT NULL, action_type VARCHAR(32) DEFAULT '' NOT NULL, alias_redirects INTEGER DEFAULT 1 NOT NULL, id INTEGER DEFAULT 0 NOT NULL, is_alias INTEGER DEFAULT 0 NOT NULL, is_original INTEGER DEFAULT 0 NOT NULL, lang_mask BIGINT DEFAULT 0 NOT NULL, link INTEGER DEFAULT 0 NOT NULL, text CLOB NOT NULL, PRIMARY KEY(parent, text_md5));
